  description: 'Image with load state, blur-up placeholder, graceful fallback, and optional zoom',
  category: 'display',
  // A plain <img> is in the server HTML; the machine only handles the blur-up and error
  // fallback.
  clientJs: 'enhancement',
  states: ['loading', 'loaded', 'error'],
  variants: [],
  sizes: [],
  props: [
    { name: 'src', description: 'Image source URL.', type: 'string', required: false },
    {
      name: 'alt',
      default: '',
      description: 'Alternative text describing the image.',
      type: 'string',
      required: false,
    },
    {
      name: 'fallbackSrc',
      type: 'string',
      required: false,
      description: 'Image shown if src fails to load',
    },
    {
      name: 'width',
      description:
        'Intrinsic width in px, forwarded to the `<img>`. Set it together with `height` so the browser can reserve the box before the image loads (no layout shift).',
      type: 'string | number',
      required: false,
    },
    {
      name: 'height',
      description:
        'Intrinsic height in px, forwarded to the `<img>`. Pair with `width` to reserve the box and avoid layout shift.',
      type: 'string | number',
      required: false,
    },
    {
      name: 'radius',
      description: "Corner radius of the image ('none' | 'sm' | 'md' | 'lg' | 'full').",
      type: "'none' | 'sm' | 'md' | 'lg' | 'full'",
      required: false,
      default: 'md',
    },
    {
      name: 'zoom',
      description: 'When true, zooms the image on hover.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
    {
      name: 'removeWrapper',
      type: 'boolean',
      required: false,
      default: 'false',
      description: 'Render a bare <img> with no wrapper, placeholder, or zoom',
    },
    {
      name: 'isBlurred',
      description: 'When true, renders a blurred backdrop behind the image.',
      type: 'boolean',
      required: false,
      default: 'false',
    },
  ],
  tokens: [
    '--cascivo-radius-none',
    '--cascivo-radius-sm',
    '--cascivo-radius-md',
    '--cascivo-radius-lg',
    '--cascivo-radius-full',
    '--cascivo-color-bg-subtle',
    '--cascivo-color-border',
    '--cascivo-space-12',
  ],
  accessibility: {
    role: 'img',
    wcag: '2.2-AA',
    keyboard: [],
    reducedMotion: true,
  },
  examples: [
    { title: 'Basic', code: '<Image src="/photo.jpg" alt="A photo" width={320} height={240} />' },
    {
      title: 'With fallback',
      code: '<Image src="/broken.jpg" fallbackSrc="/placeholder.jpg" alt="A photo" />',
    },
    { title: 'Blurred placeholder', code: '<Image src="/photo.jpg" alt="A photo" isBlurred />' },
    { title: 'Hover zoom', code: '<Image src="/photo.jpg" alt="A photo" zoom />' },
  ],
  dependencies: ['@cascivo/core'],
  tags: ['image', 'media', 'display', 'loading'],
  intent: {
    whenToUse: [
      'Displaying a content image that should show a placeholder while loading and degrade gracefully on error',
      'Photos, thumbnails, or media that benefit from a blur-up placeholder or hover zoom',
      'Any image where a broken src should fall back rather than show a broken-image icon',
    ],
    whenNotToUse: [
      'Identity thumbnails for a person or entity — use Avatar',
      'Purely decorative shapes or a fixed-ratio layout box with no load behavior — use AspectRatio',
    ],
    antiPatterns: [
      {
        bad: '<Image src="/photo.jpg" /> with no alt',
        good: '<Image src="/photo.jpg" alt="Sunset over the bay" />',
        why: 'Without alt the image is invisible to assistive tech; pass an empty alt only for decorative images',
      },
    ],
    related: [
      {
        name: 'Avatar',
        relationship: 'alternative',
        reason: 'Use Avatar for identity thumbnails with an initials fallback',
      },
      {
        name: 'AspectRatio',
        relationship: 'alternative',
        reason: 'Use AspectRatio for a ratio box that does not own image load behavior',
      },
    ],
    a11yRationale:
      'role="img" with alt names the image; on error it shows a fallback image or neutral box so layout survives; the blur-up and zoom transitions are disabled under prefers-reduced-motion',
    flexibility: [
      {
        area: 'radius',
        level: 'flexible',
        note: 'Pick the corner radius that matches the surrounding surface',
      },
      {
        area: 'token names',
        level: 'strict',
        note: 'Radius and placeholder colors must resolve to --cascivo-* tokens',
      },
    ],
  },
